# Generated by manage.py generate_test_cases.
"""Focused scenarios for target-native Set value configuration."""

from unittest.mock import patch

from django import forms
from django.core.exceptions import ValidationError

from bloomerp.form_behaviors.builtins.set_value import SET_VALUE
from bloomerp.form_behaviors.definition import (
    BehaviorContext,
    BehaviorResult,
    FieldValueUpdate,
)
from bloomerp.tests.base import (
    BehaviorActionScenario,
    BloomerpBehaviorActionTestCase,
    ExpectedBehaviorActionException,
)


class TestSetValueAction(BloomerpBehaviorActionTestCase):
    """Verify typed scalar, relation, empty, and unavailable target handling."""

    action = SET_VALUE
    create_foreign_models = True

    def _context(self, target_field: str) -> BehaviorContext:
        """Build a draft context whose listener and target belong to the customer."""
        return BehaviorContext(
            values={"first_name": "Draft", target_field: None},
            listener_field="first_name",
            target_field=target_field,
        )

    def get_test_scenarios(self) -> list[BehaviorActionScenario]:
        """Cover native text, numeric, relation, empty, and invalid input cleaning."""
        listener = self.get_application_field("first_name")
        text_target = self.get_application_field("last_name")
        number_target = self.get_application_field("age")
        relation_target = self.get_application_field("country")
        country = self.CountryModel.objects.get(name="Belgium")
        return [
            BehaviorActionScenario(
                name="Text values retain their native string representation",
                context=self._context("last_name"),
                listener=listener,
                target=text_target,
                config={"value": "Restored text"},
                expected_result=BehaviorResult(
                    values=(FieldValueUpdate(field="last_name", value="Restored text"),)
                ),
            ),
            BehaviorActionScenario(
                name="Numeric strings are coerced by the target integer field",
                context=self._context("age"),
                listener=listener,
                target=number_target,
                config={"value": "24"},
                expected_result=BehaviorResult(
                    values=(FieldValueUpdate(field="age", value=24),)
                ),
            ),
            BehaviorActionScenario(
                name="Relation identifiers are resolved by the native choice field",
                context=self._context("country"),
                listener=listener,
                target=relation_target,
                config={"value": str(country.pk)},
                expected_result=BehaviorResult(
                    values=(FieldValueUpdate(field="country", value=str(country.pk)),)
                ),
            ),
            BehaviorActionScenario(
                name="The historically supported empty configured value remains valid",
                context=self._context("last_name"),
                listener=listener,
                target=text_target,
                config={"value": ""},
                expected_result=BehaviorResult(
                    values=(FieldValueUpdate(field="last_name", value=""),)
                ),
            ),
            BehaviorActionScenario(
                name="Invalid numeric input is rejected during configuration cleaning",
                context=self._context("age"),
                listener=listener,
                target=number_target,
                config={"value": "not-an-integer"},
                expected_exception=ExpectedBehaviorActionException(ValidationError),
            ),
        ]

    def test_configuration_uses_target_native_fields_and_widgets(self) -> None:
        """Each dynamic form reuses the selected target's registered form contract."""
        listener = self.get_application_field("first_name")
        integer_form = SET_VALUE.config_form_factory(
            self.get_application_field("age"), listener
        )
        relation_form = SET_VALUE.config_form_factory(
            self.get_application_field("country"), listener
        )
        self.assertIsInstance(integer_form.base_fields["value"], forms.IntegerField)
        self.assertIsInstance(
            relation_form.base_fields["value"], forms.ModelChoiceField
        )
        self.assertFalse(integer_form.base_fields["value"].required)
        self.assertFalse(relation_form.base_fields["value"].required)

    def test_configuration_rejects_missing_or_non_editable_targets(self) -> None:
        """Dynamic form construction fails clearly instead of installing a None field."""
        with self.assertRaisesMessage(ValidationError, "Select a target field first"):
            SET_VALUE.config_form_factory(None, None)

        target = self.get_application_field("last_name")
        with (
            patch.object(target, "get_form_field", return_value=None),
            self.assertRaisesMessage(ValidationError, "cannot accept a value"),
        ):
            SET_VALUE.config_form_factory(target, None)
